function resolvePopErrorMessage(data: any, result: number, message: unknown) {
  if (data?.fallback_sms === true) {
    return '该地区未支持该验证码下发方式'
  }
  if (result !== 0 && typeof message === 'string' && message.trim()) {
    return message.trim()
  }
  return ''
}

function reportVoiceCodePopClick(codeType: number, modalSource: string, errorMessage: string) {
  reportEvent(Events.h5_common_pop_click, {
    location: 'H5授权手机登录页',
    size: 3,
    pop_type: 'voice_code_modal',
    url: window.location.href,
    source: modalSource,
    element_name: voiceCodeElementNameMap[codeType] || '',
    error_message: errorMessage,
  })
}

async function getCode(
  codeType: number,
  fromVoiceCodeModal: boolean,
  retry = 0,
  modalSource = '',
  carriedErrorMessage = ''
) {
  if (sendCodeBtnStatus.value === SendCodeBtnStatus.COOLING && !fromVoiceCodeModal) {
    return
  }

  if (!mobile.value) {
    showToast(_T('请输入您的手机号'))
    reportCodeResult(`${country.value}`, `${mobile.value}`, 'failed', `请输入您的手机号`, codeType)
    return
  }
  if (!country.value) {
    showToast(_T('请选择国家/地区'))
    reportCodeResult(`${country.value}`, `${mobile.value}`, 'failed', `请选择国家/地区`, codeType)
    return
  }

  const number = `+${country.value}  ${mobile.value}`
  if (!validateMobile(number)) {
    showToast(_T('手机号码输入有误，请调整后重试'))
    reportCodeResult(
      `${country.value}`,
      `${mobile.value}`,
      'failed',
      `手机号码输入有误，请调整后重试`,
      codeType
    )
    return
  }

  if (loading.value) {
    return
  }
  loading.value = true
  try {
    reportClick('send_code', `${mobile.value}`, `${country.value}`)
  } catch (error) {
    reportError(error)
  }

  // 上报结果
  const [success, { result, data, message, toast }] = await getMobileCode(
    mobile.value,
    country.value,
    codeType,
    showPageTime,
    /* eslint-disable no-unneeded-ternary */
    fromVoiceCodeModal && codeType === 0 ? true : false,
    'login'
  )
  loading.value = false

  console.log('getMobileCode:', success, result, data, message)

  const currentErrorMessage = resolvePopErrorMessage(data, result, message)
  const errorMessage = currentErrorMessage || carriedErrorMessage
  if (fromVoiceCodeModal && !(result === -20000 && retry === 0)) {
    reportVoiceCodePopClick(codeType, modalSource, errorMessage)
  }

  // {
  //   // device token失效
  //   showModal(TokenModal, {
  //     cb: () => {
  //       refreshDeviceToken(mobile.value, country.value, countryFlag.value)
  //     },
  //   })
  //   return
  // }
  if (success && result === 0) {
    //
  } else {
    reportEvent(Events.user_login_report_failed, {
      source: 'sawa',
      status_string: isDiwania.value ? 'diwaniaH5_mobile' : 'sawaksaH5_mobile',
      error_code: `${result}`,
      error_content: message || '',
      is_sawaapp_authorize: false,
      h5_type: 'phone',
      type: '登录',
      h5_scene: 'get_code',
    })
  }
  reportCodeResult(
    `${country.value}`,
    `${mobile.value}`,
    result === 0 ? 'succeed' : 'failed',
    `${message || ''}`,
    codeType
  )

  if (success && result === 0) {
    const extraToast = typeof data?.extra_toast === 'string' ? data.extra_toast.trim() : ''
    if (extraToast) {
      showToast(extraToast)
    }
    if (data?.more_code_type?.length > 0) {
      showVoiceCodeModal('申请验证码连续失败')
    } else {
      cooldown.start(getSysTs())
    }
  } else if (result === -20000) {
    if (retry > 0) {
      return
    }
    await startCA()
    getCode(codeType, fromVoiceCodeModal, retry + 1, modalSource, errorMessage)
  } else if (result === -10001) {
    // device token失效
    showModal(TokenModal, {
      cb: () => {
        refreshDeviceToken(mobile.value, country.value, countryFlag.value)
      },
    })
  } else if (toast) {
    showToast(toast)
  }
}

async function login() {
  // 旧版兼容
  const v2 = getAppClientVersion()
  const oldVersion = getPlatform().isIPhone && (!v2 || Number(v2) < 10258)
  if (oldVersion) {
    oldLogin()
    return
  }

  // 需要有手机号 国家码 验证码
  if (!mobile.value) {
    showToast(_T('请输入您的手机号'))
    return
  }
  if (!code.value) {
    showToast(_T('请输入验证码'))
    return
  }
  if (!country.value) {
    showToast(_T('请选择国家/地区'))
    return
  }

  // 提交登录
  try {
    reportClick('submit', `${mobile.value}`, `${country.value}`)
  } catch (error) {
    reportError(error)
  }
  if (loading.value) return
  loading.value = true
  const [success, resp] = await queryBindedAccounts({
    country_code: country.value,
    mobile: String(mobile.value),
    code: String(code.value),
    not_auto_create: true,
  })
  if (!success) {
    showToast(_T('获取数据失败，请稍后重试'))
    return
  }
  loading.value = false
  const { result, data, message, toast } = resp
  const { identities, login_key, can_create } = data || {}
  console.log('checkBindedLogin', result, data, message)
  // if (mobile.value === '99992025') {
  //   return
  // }
  console.warn('[mobile]', mobile.value)

  // 1) 没有账号，是否自动创建
  if (result !== 0) {
    reportEvent(Events.user_login_report_failed, {
      source: 'sawa',
      status_string: isDiwania.value ? 'diwaniaH5_mobile' : 'sawaksaH5_mobile',
      error_code: `${result}`,
      error_content: message || '',
      is_sawaapp_authorize: false,
      h5_type: 'phone',
      type: '登录',
      h5_scene: 'login',
    })
    if (result === 20001) {
      showBanToast(message || '')
      return
    }
    if (result === 20193) {
      unregisterRemind(resp)
      return
    }
    if (result === 20312) {
      showCreateModal(() => createAccount(login_key), 'phone')
      return
    }
    if (result === 20063) {
      showToast(_T('ip注册频繁'))
      return
    }
    if (result === 20064) {
      showToast(_T('注册失败，设备注册账号已到达上限'))
      return
    }
    if (toast) {
      // 手机绑定已达最大数量
      showToast(toast)
    }
    return
  }

  // 2) 有 user_info 自动登录
  if (data && data.user_info && data.user_info.session_key) {
    session_key.value = data.user_info.session_key
    refreshAccount({ data }, 'sawaksa_mobile', isDiwania.value ? 'diwaniaH5_mobile' : 'sawaksaH5_mobile')
    return
  }

  // 3) 没有user_info 也没有多帐号，自动创建
  const accounts = identities.filter((t: any) =>
    [UserSource.KSA, UserSource.DIWANIA, UserSource.LUDO].includes(t.user_source)
  )
  if (accounts.length === 0) {
    showCreateModal(() => createAccount(login_key), 'phone')
    return
  }

  // 4) 只有1个账号 且 手机号不能在ksa注册，自动登录
  if (accounts.length === 1 && !can_create) {
    const p1 = accounts[0]
    const [success, resp] = await selectBindedAccount({
      login_key: p1.login_key,
      uid: p1.uid,
    })
    const { result, data, message } = resp || {}
    if (success && data && data.user_info && data.user_info.session_key) {
      refreshAccount({ data }, 'sawaksa_mobile', isDiwania.value ? 'diwaniaH5_mobile' : 'sawaksaH5_mobile')
      return
    }
    if (result === 20001) {
      showBanToast(message || '')
      return
    }
    if (result === 20193) {
      unregisterRemind(resp)
      return
    }
    if (result === 20312) {
      showCreateModal(() => createAccount(login_key), 'phone')
      return
    }
    if (result === 20063) {
      showToast(_T('ip注册频繁'))
      return
    }
    if (result === 20064) {
      showToast(_T('注册失败，设备注册账号已到达上限'))
      return
    }
    showToast(_T('获取数据失败，请稍后重试'))
    return
  }

  // 5) 其他情况，展示多账号列表
  goAccountsSelectingPage(resp, String(mobile.value), String(code.value), 'sawaksa_mobile')
}

async function oldLogin(auto_create = false) {
  // 需要有手机号 国家码 验证码
  if (!mobile.value) {
    showToast(_T('请输入您的手机号'))
    return
  }
  if (!code.value) {
    showToast(_T('请输入验证码'))
    return
  }
  if (!country.value) {
    showToast(_T('请选择国家/地区'))
    return
  }

  // 提交登录
  try {
    reportClick('submit', `${mobile.value}`, `${country.value}`)
  } catch (error) {
    reportError(error)
  }
  if (loading.value) {
    return
  }
  loading.value = true
  // 登录拿到 session_key
  const [success, resp] = await loginWithMobile(
    mobile.value,
    code.value,
    country.value,
    auto_create
  )
  const { result, data, message, toast } = resp
  console.log('loginWithMobile:', success, result, data, message)
  if (!success) {
    loading.value = false
    showToast(_T('获取数据失败，请稍后重试'))
    return
  }
  // 没有账号，是否自动创建
  if (result !== 0) {
    loading.value = false
    if (result === 20193) {
      unregisterRemind(resp)
    }
    if (result === 20312) {
      showCreateModal(() => oldLogin(true), 'phone')
    }
    if (result === 20063) {
      showToast(_T('ip注册频繁'))
    }
    if (result === 20064) {
      showToast(_T('注册失败，设备注册账号已到达上限'))
    }
    if (result === 32200) {
      // 手机绑定已达最大数量
      showToast(toast)
    }
    if (toast) {
      showToast(toast)
    }
    return
  }

  if (data && data.user_info && data.user_info.session_key) {
    session_key.value = data.user_info.session_key
    refreshAccount({ data }, 'sawaksa_mobile', isDiwania.value ? 'diwaniaH5_mobile' : 'sawaksaH5_mobile')
  }
  loading.value = false
}

